import subprocess,json
s=subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True)
d=json.loads(s)
for k,v in d.items():
 if k"'!='"'context': print(k,json.dumps(v))
c=d.get('context',{})
print('CONTEXT_KEYS',list(c))
for k,v in c.items():
 if k=='history':
  for t in v:
   print('TRIAL',json.dumps({key:t.get(key) for key in ['id','parent','role','config','status','parameters','wall_seconds','error','note']}), 'validation',json.dumps({key:t.get('validation',{}).get(key) for key in ['auc','logloss','samples']}))
 else:
  print('CONTEXT',k, json.dumps(v)[:14000])
PY"

